// Last-resort crash surface — self-installing on import. A detached/secondary window's logs may
// never reach the Tauri sink (the IPC/log bridge can be absent in a runtime-created window), so a
// crash there is otherwise invisible — blank window, no logs (#tab-tearoff). This is PURE DOM (no
// Tauri dependency) and registers its handlers at IMPORT time, so it surfaces the real error/stack
// even for module-eval and pre-React failures — provided this module is imported FIRST.

// Browser warnings that fire as window `error` events but are NOT real crashes — never overlay on
// these. "ResizeObserver loop …" is benign (a resize callback caused more layout; the browser just
// deferred a frame) and fires constantly on resizable/observed layouts like the planner split panes.
// "Script error." is the opaque cross-origin placeholder with no actionable detail.
const BENIGN = [
  "ResizeObserver loop limit exceeded",
  "ResizeObserver loop completed with undelivered notifications",
  "Script error.",
];
/** True for harmless browser warnings the overlay must ignore (exported for tests). */
export const isBenign = (msg: string) => BENIGN.some((b) => msg.includes(b));

let shown = false;
/** Hand the crash to the backend, so it outlives this window.
 *
 *  The overlay is PURE DOM on purpose — it must render even where the Tauri bridge is absent, which is
 *  the case it was written for. So this reaches the bridge through the global rather than importing
 *  anything, and treats every failure as expected: it is a BONUS path, not the mechanism.
 *
 *  Without it, the durable record of a boot crash is the launch watchdog's message-less "the UI never
 *  mounted", because everything the overlay knows dies with the window it painted into. With it, the
 *  same fault carries the actual error. Nothing here may throw or block: the overlay's own job — being
 *  the last thing a user can see — comes first. */
function report(title: string, detail: string) {
  try {
    const bridge = (globalThis as { __TAURI_INTERNALS__?: { invoke?: (c: string, a: unknown) => Promise<unknown> } })
      .__TAURI_INTERNALS__;
    void bridge?.invoke?.("boot_failed", { message: `${title}: ${detail.split("\n")[0]}`, detail })
      ?.catch(() => { /* an older backend has no such command; the watchdog still files it */ });
  } catch { /* no bridge in this window — expected, and exactly why the overlay is pure DOM */ }
}

/** Paint the crash and hand it to the backend. Exported for tests: the window `error` listener this
 *  module installs cannot be un-installed, so a test that drove the overlay through real events would
 *  be counting the handlers of every module instance a previous test loaded rather than this one's. */
export function show(title: string, detail: string) {
  if (shown) return; // first real fatal only — don't stack overlays on repeated errors
  shown = true;
  report(title, detail);
  try {
    const el = document.createElement("pre");
    el.setAttribute("data-fatal-overlay", "");
    el.style.cssText =
      "position:fixed;inset:0;z-index:99999;margin:0;padding:16px;overflow:auto;" +
      "background:#181a1e;color:#ff6b6b;font:11px/1.55 ui-monospace,monospace;white-space:pre-wrap;word-break:break-word;";
    el.textContent = `${title}\n\n${detail}`;
    (document.body || document.documentElement).appendChild(el);
  } catch { /* nothing more we can do */ }
}

/** Has the app rendered? Pure DOM, like everything else here — `main.tsx` renders into `#root`, so a
 *  root with children is React having mounted at least once.
 *
 *  This module exists for "module-eval and pre-React failures" (see the header) — a boot that never
 *  paints, where the only alternative is a blank window and the watchdog's message-less "the UI never
 *  mounted". AFTER the app is up, the same handlers are the wrong tool twice over:
 *
 *  • `show` paints `position:fixed;inset:0;z-index:99999` over a WORKING app. A stray rejection from
 *    a background poll then looks exactly like a crash, because it covers everything.
 *  • `report` calls `boot_failed`, which files a durable LAUNCH fault. A fault outlives the session
 *    and stays amber in Glance, so a post-mount hiccup becomes a permanent lie about the boot.
 *
 *  Observed: `Unhandled promise rejection: @user-script:8:11:75` logged as a "fatal boot error"
 *  22 seconds AFTER `render→mounted` and `hydrated→painted` — with the app then going on to launch a
 *  full fleet. Nothing was wrong with the boot.
 *
 *  Deliberately NOT solved by adding these messages to {@link BENIGN}: `Importing a module script
 *  failed.` is sometimes a dev-server transient and sometimes a genuinely broken record module, and
 *  a blanket filter would hide the second kind forever. Mount state is the honest discriminator —
 *  it separates "the app never came up" from "the app is up and something threw". */
function hasMounted(): boolean {
  try {
    return (document.getElementById("root")?.childElementCount ?? 0) > 0;
  } catch {
    return false; // no DOM to ask — treat as pre-mount, the louder direction
  }
}

/** Route one caught failure: overlay + backend fault before mount, console only after.
 *
 *  Never silent. Post-mount still reaches the Rust log through the app's console bridge, so the
 *  record survives — it just stops claiming the BOOT failed and stops covering the UI. */
export function handle(title: string, detail: string) {
  if (isBenign(detail)) return;
  if (hasMounted()) {
    // eslint-disable-next-line no-console
    console.error(`[post-mount] ${title}: ${detail}`);
    return;
  }
  show(title, detail);
}

window.addEventListener("error", (e) => {
  handle("Uncaught error", (e.error && (e.error.stack || e.error.message)) || e.message || String(e));
});
window.addEventListener("unhandledrejection", (e) => {
  const r = (e as PromiseRejectionEvent).reason;
  handle("Unhandled promise rejection", (r && (r.stack || r.message)) || String(r));
});

